import openpyxl
from openpyxl.utils import get_column_letter
golden='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/2_49237_answer_template_6134_golden.xlsx'
out='/tmp/llm_rollout_6w33y36o/final_2_49237_answer_template_6134.xlsx'
wb1=openpyxl.load_workbook(golden, data_only=False)
ws1=wb1.active
wb2=openpyxl.load_workbook(out, data_only=False)
ws2=wb2.active

def border(c):
    b=c.border
    return (b.left.style, b.right.style, b.top.style, b.bottom.style, b.diagonal.style)
def font(c):
    f=c.font
    return (f.name, f.sz, f.bold, f.italic, f.color.type if f.color else None, getattr(f.color,'rgb',None))
def align(c):
    a=c.alignment
    return (a.horizontal, a.vertical, a.wrap_text, a.shrink_to_fit)

diffs=[]
for r in range(1,28):
    for c in range(1,13):
        coord=f'{get_column_letter(c)}{r}'
        a=ws1.cell(row=r,column=c); b=ws2.cell(row=r,column=c)
        if border(a)!=border(b):
            diffs.append((coord,'border',border(a),border(b)))
        if font(a)!=font(b):
            diffs.append((coord,'font',font(a),font(b)))
        if align(a)!=align(b):
            diffs.append((coord,'align',align(a),align(b)))
print('style diffs',len(diffs))
for d in diffs[:200]: print(d)
print('merged equal?', set(map(str,ws1.merged_cells.ranges))==set(map(str,ws2.merged_cells.ranges)), len(ws1.merged_cells.ranges), len(ws2.merged_cells.ranges))
print('cf count', len(ws1.conditional_formatting), len(ws2.conditional_formatting))
print('row heights equal?', all(ws1.row_dimensions[r].height==ws2.row_dimensions[r].height for r in range(1,28) if r in ws1.row_dimensions or r in ws2.row_dimensions))
print('col widths equal?', all(ws1.column_dimensions[c].width==ws2.column_dimensions[c].width for c in 'ABCDEFGHIJKL' if c in ws1.column_dimensions or c in ws2.column_dimensions))
wb1.close(); wb2.close()
